-- SOLO base temporal después de CAS crudo. Conservar fila fuente como clave técnica.
-- Lote 2018: 67339 CAS, 1936753 celdas, 658360 vacíos.
BEGIN;
INSERT INTO electoral_stage.casilla_tally(series_id,cas_member_id,unit_id,raw_row_id,casilla_key,original_identity,total_votes,total_raw,nominal_list,nominal_raw,estatus_acta,tribunal,juicio,observaciones,ruta_acta) SELECT scm.series_id,rr.member_id,cu.unit_id,rr.raw_row_id,'CASROW:'||rr.member_id||':'||rr.source_line,jsonb_build_object('ID_ESTADO',rr.raw_cells->>'ID_ESTADO','ID_DISTRITO_FEDERAL',coalesce(rr.raw_cells->>'ID_DISTRITO_FEDERAL',rr.raw_cells->>'ID_DISTRITO'),'ID_DISTRITO_LOCAL',rr.raw_cells->>'ID_DISTRITO_LOCAL','ID_MUNICIPIO',rr.raw_cells->>'ID_MUNICIPIO','MUNICIPIO',rr.raw_cells->>'MUNICIPIO','SECCION',rr.raw_cells->>'SECCION','TIPO_CASILLA',rr.raw_cells->>'TIPO_CASILLA','ID_CASILLA',rr.raw_cells->>'ID_CASILLA','EXT_CONTIGUA',rr.raw_cells->>'EXT_CONTIGUA','CASILLA',rr.raw_cells->>'CASILLA','ACTA_CASILLA-MEC',rr.raw_cells->>'ACTA_CASILLA-MEC','source_line',rr.source_line),nullif(rr.raw_cells->>'TOTAL_VOTOS','')::bigint,rr.raw_cells->>'TOTAL_VOTOS',nullif(rr.raw_cells->>'LISTA_NOMINAL','')::bigint,rr.raw_cells->>'LISTA_NOMINAL',rr.raw_cells->>'ESTATUS_ACTA',rr.raw_cells->>'TRIBUNAL',rr.raw_cells->>'JUICIO',rr.raw_cells->>'OBSERVACIONES',rr.raw_cells->>'RUTA_ACTA' FROM electoral_stage.raw_row rr JOIN electoral_stage.series_cas_member scm ON scm.cas_member_id=rr.member_id JOIN electoral_stage.election_series es ON es.series_id=scm.series_id JOIN electoral_stage.computation_unit cu ON cu.series_id=es.series_id AND cu.unit_key=CASE WHEN rr.raw_cells->>'SECCION'='0' THEN 'SEC0:'||jsonb_build_array(CASE WHEN es.election_type IN ('DF','P','S') THEN coalesce(rr.raw_cells->>'ID_DISTRITO_FEDERAL',rr.raw_cells->>'ID_DISTRITO','') ELSE '' END,coalesce(rr.raw_cells->>'ID_DISTRITO_LOCAL',''),coalesce(rr.raw_cells->>'ID_MUNICIPIO',''),coalesce(rr.raw_cells->>'MUNICIPIO',''))::text ELSE 'SEC:'||(rr.raw_cells->>'SECCION') END AND cu.state_code=rr.raw_cells->>'ID_ESTADO' WHERE es.election_year=2018;
INSERT INTO electoral_stage.casilla_option_vote(series_id,casilla_id,option_id,votes,raw_value,missing_cause) SELECT ct.series_id,ct.casilla_id,oc.option_id,nullif(rr.raw_cells->>oc.literal_header,'')::bigint,rr.raw_cells->>oc.literal_header,CASE WHEN rr.raw_cells->>oc.literal_header='' THEN 'LITERAL_BLANK' END FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id JOIN electoral_stage.raw_row rr ON rr.member_id=ct.cas_member_id AND rr.raw_row_id=ct.raw_row_id JOIN electoral_stage.option_column oc ON oc.series_id=ct.series_id WHERE es.election_year=2018 AND rr.raw_cells ? oc.literal_header;
DO $$ DECLARE u bigint; c bigint; b bigint; BEGIN SELECT count(*) INTO u FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id WHERE es.election_year=2018; SELECT count(*),count(*) FILTER (WHERE cov.votes IS NULL) INTO c,b FROM electoral_stage.casilla_option_vote cov JOIN electoral_stage.election_series es ON es.series_id=cov.series_id WHERE es.election_year=2018; IF u<>67339 OR c<>1936753 OR b<>658360 THEN RAISE EXCEPTION 'CAS 2018: %, %, %',u,c,b; END IF; RAISE NOTICE 'CAS 2018 OK: % filas, % celdas, % vacíos',u,c,b; END $$;
COMMIT;
-- Lote 2021: 38817 CAS, 791751 celdas, 144959 vacíos.
BEGIN;
INSERT INTO electoral_stage.casilla_tally(series_id,cas_member_id,unit_id,raw_row_id,casilla_key,original_identity,total_votes,total_raw,nominal_list,nominal_raw,estatus_acta,tribunal,juicio,observaciones,ruta_acta) SELECT scm.series_id,rr.member_id,cu.unit_id,rr.raw_row_id,'CASROW:'||rr.member_id||':'||rr.source_line,jsonb_build_object('ID_ESTADO',rr.raw_cells->>'ID_ESTADO','ID_DISTRITO_FEDERAL',coalesce(rr.raw_cells->>'ID_DISTRITO_FEDERAL',rr.raw_cells->>'ID_DISTRITO'),'ID_DISTRITO_LOCAL',rr.raw_cells->>'ID_DISTRITO_LOCAL','ID_MUNICIPIO',rr.raw_cells->>'ID_MUNICIPIO','MUNICIPIO',rr.raw_cells->>'MUNICIPIO','SECCION',rr.raw_cells->>'SECCION','TIPO_CASILLA',rr.raw_cells->>'TIPO_CASILLA','ID_CASILLA',rr.raw_cells->>'ID_CASILLA','EXT_CONTIGUA',rr.raw_cells->>'EXT_CONTIGUA','CASILLA',rr.raw_cells->>'CASILLA','ACTA_CASILLA-MEC',rr.raw_cells->>'ACTA_CASILLA-MEC','source_line',rr.source_line),nullif(rr.raw_cells->>'TOTAL_VOTOS','')::bigint,rr.raw_cells->>'TOTAL_VOTOS',nullif(rr.raw_cells->>'LISTA_NOMINAL','')::bigint,rr.raw_cells->>'LISTA_NOMINAL',rr.raw_cells->>'ESTATUS_ACTA',rr.raw_cells->>'TRIBUNAL',rr.raw_cells->>'JUICIO',rr.raw_cells->>'OBSERVACIONES',rr.raw_cells->>'RUTA_ACTA' FROM electoral_stage.raw_row rr JOIN electoral_stage.series_cas_member scm ON scm.cas_member_id=rr.member_id JOIN electoral_stage.election_series es ON es.series_id=scm.series_id JOIN electoral_stage.computation_unit cu ON cu.series_id=es.series_id AND cu.unit_key=CASE WHEN rr.raw_cells->>'SECCION'='0' THEN 'SEC0:'||jsonb_build_array(CASE WHEN es.election_type IN ('DF','P','S') THEN coalesce(rr.raw_cells->>'ID_DISTRITO_FEDERAL',rr.raw_cells->>'ID_DISTRITO','') ELSE '' END,coalesce(rr.raw_cells->>'ID_DISTRITO_LOCAL',''),coalesce(rr.raw_cells->>'ID_MUNICIPIO',''),coalesce(rr.raw_cells->>'MUNICIPIO',''))::text ELSE 'SEC:'||(rr.raw_cells->>'SECCION') END AND cu.state_code=rr.raw_cells->>'ID_ESTADO' WHERE es.election_year=2021;
INSERT INTO electoral_stage.casilla_option_vote(series_id,casilla_id,option_id,votes,raw_value,missing_cause) SELECT ct.series_id,ct.casilla_id,oc.option_id,nullif(rr.raw_cells->>oc.literal_header,'')::bigint,rr.raw_cells->>oc.literal_header,CASE WHEN rr.raw_cells->>oc.literal_header='' THEN 'LITERAL_BLANK' END FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id JOIN electoral_stage.raw_row rr ON rr.member_id=ct.cas_member_id AND rr.raw_row_id=ct.raw_row_id JOIN electoral_stage.option_column oc ON oc.series_id=ct.series_id WHERE es.election_year=2021 AND rr.raw_cells ? oc.literal_header;
DO $$ DECLARE u bigint; c bigint; b bigint; BEGIN SELECT count(*) INTO u FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id WHERE es.election_year=2021; SELECT count(*),count(*) FILTER (WHERE cov.votes IS NULL) INTO c,b FROM electoral_stage.casilla_option_vote cov JOIN electoral_stage.election_series es ON es.series_id=cov.series_id WHERE es.election_year=2021; IF u<>38817 OR c<>791751 OR b<>144959 THEN RAISE EXCEPTION 'CAS 2021: %, %, %',u,c,b; END IF; RAISE NOTICE 'CAS 2021 OK: % filas, % celdas, % vacíos',u,c,b; END $$;
COMMIT;
