DO $$ DECLARE u bigint; c bigint; b bigint; BEGIN SELECT count(*) INTO u FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id WHERE es.election_year=2024; SELECT count(*),count(*) FILTER (WHERE cov.votes IS NULL) INTO c,b FROM electoral_stage.casilla_option_vote cov JOIN electoral_stage.election_series es ON es.series_id=cov.series_id WHERE es.election_year=2024; IF u<>73623 OR c<>1333364 OR b<>16318 THEN RAISE EXCEPTION 'CAS 2024: %, %, %',u,c,b; END IF; RAISE NOTICE 'CAS 2024 OK: % filas, % celdas, % vacíos',u,c,b; END $$;
