SELECT es.election_year,es.election_type,es.modality,count(*) AS casillas FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id GROUP BY 1,2,3 ORDER BY 1,2,3;
